import { Injectable } from '@angular/core';
import { Observable, of } from 'rxjs';
import { MoodEntry, MoodEmoji, MOOD_EMOJIS } from '../models/wellness.model';

@Injectable({
  providedIn: 'root'
})
export class MoodCheckinService {
  private readonly storageKey = 'kca_mood_entries';

  constructor() {}

  saveMoodEntry(entry: MoodEntry): Observable<MoodEntry> {
    const entries = this.getStoredEntries();
    entries.unshift(entry);
    this.saveEntries(entries);
    return of(entry);
  }

  getMoodEntries(userId: string = 'current-user'): Observable<MoodEntry[]> {
    const entries = this.getStoredEntries().filter(e => e.userId === userId);
    return of(entries);
  }

  getMoodEntriesForPeriod(userId: string, days: number): Observable<MoodEntry[]> {
    const entries = this.getStoredEntries().filter(e => e.userId === userId);
    const cutoff = new Date();
    cutoff.setDate(cutoff.getDate() - days);
    const filtered = entries.filter(e => new Date(e.timestamp) >= cutoff);
    return of(filtered);
  }

  getMoodEmojis(): MoodEmoji[] {
    return MOOD_EMOJIS;
  }

  getMoodEmojiById(id: string): MoodEmoji | undefined {
    return MOOD_EMOJIS.find(e => e.id === id);
  }

  getAverageMood(userId: string, days: number = 7): Observable<number> {
    const entries = this.getStoredEntries()
      .filter(e => e.userId === userId)
      .slice(0, days);
    if (entries.length === 0) return of(3);
    const sum = entries.reduce((acc, e) => acc + e.mood.value, 0);
    return of(sum / entries.length);
  }

  getMoodTrend(userId: string, days: number = 14): Observable<{ date: string; value: number }[]> {
    const entries = this.getStoredEntries()
      .filter(e => e.userId === userId)
      .sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
      .slice(-days);
    const trend = entries.map(e => ({
      date: new Date(e.timestamp).toISOString().split('T')[0],
      value: e.mood.value
    }));
    return of(trend);
  }

  getMoodDistribution(userId: string): Observable<Record<string, number>> {
    const entries = this.getStoredEntries().filter(e => e.userId === userId);
    const distribution: Record<string, number> = {};
    entries.forEach(e => {
      distribution[e.mood.id] = (distribution[e.mood.id] || 0) + 1;
    });
    return of(distribution);
  }

  private getStoredEntries(): MoodEntry[] {
    try {
      const data = localStorage.getItem(this.storageKey);
      return data ? JSON.parse(data) : [];
    } catch {
      return [];
    }
  }

  private saveEntries(entries: MoodEntry[]): void {
    try {
      localStorage.setItem(this.storageKey, JSON.stringify(entries));
    } catch (e) {
      console.warn('Failed to save mood entries to localStorage', e);
    }
  }
}