export class QuickHelpComponent {
  user = { firstName: 'John' };

  quickHelpOptions = QUICK_HELP_OPTIONS.map(opt => ({
    ...opt,
    icon: this.getIconForCategory(opt.id),
    iconColor: this.getIconColor(opt.id)
  }));

  navItems: NavItem[] = [
    { label: 'Dashboard', route: '/student/dashboard', icon: 'dashboard' },
    { label: 'Quick Help', route: '/student/quick-help', icon: 'help', active: true },
    { label: 'Mood Check-in', route: '/student/mood-checkin', icon: 'activity' },
    { label: 'Quiet Space', route: '/student/quiet-space', icon: 'moon' },
    { label: 'Resources', route: '/student/wellness-resources', icon: 'book' }
  ];

  bottomNavItems = [
    { label: 'Home', route: '/student/dashboard', icon: 'home' },
    { label: 'Help', route: '/student/quick-help', icon: 'help', active: true },
    { label: 'Mood', route: '/student/mood-checkin', icon: 'activity' },
    { label: 'Quiet', route: '/student/quiet-space', icon: 'moon' },
    { label: 'Profile', route: '/student/profile', icon: 'user' }
  ];

  getIconForCategory(category: QuickHelpCategory): string {
    const icons: Record<QuickHelpCategory, string> = {
      [QuickHelpCategory.STRESS]: 'stress',
      [QuickHelpCategory.ANXIETY_WORRY]: 'anxiety',
      [QuickHelpCategory.ACADEMIC_PRESSURE]: 'academic',
      [QuickHelpCategory.RELATIONSHIPS]: 'relationship',
      [QuickHelpCategory.FAMILY_ISSUES]: 'family',
      [QuickHelpCategory.FINANCIAL_CHALLENGES]: 'financial',
      [QuickHelpCategory.CAREER_GUIDANCE]: 'career',
      [QuickHelpCategory.FRIENDSHIP_SOCIAL]: 'social',
      [QuickHelpCategory.SLEEP_WELLBEING]: 'sleep',
      [QuickHelpCategory.GENERAL_SUPPORT]: 'support',
      [QuickHelpCategory.NOT_SURE]: 'unsure',
      [QuickHelpCategory.URGENT_HELP]: 'urgent'
    };
    return icons[category] || 'support';
  }

  getIconColor(category: QuickHelpCategory): string {
    const colors: Record<QuickHelpCategory, string> = {
      [QuickHelpCategory.STRESS]: 'primary-100 text-primary',
      [QuickHelpCategory.ANXIETY_WORRY]: 'warning-light text-warning',
      [QuickHelpCategory.ACADEMIC_PRESSURE]: 'secondary-100 text-secondary',
      [QuickHelpCategory.RELATIONSHIPS]: 'accent-100 text-accent',
      [QuickHelpCategory.FAMILY_ISSUES]: 'primary-100 text-primary',
      [QuickHelpCategory.FINANCIAL_CHALLENGES]: 'warning-light text-warning',
      [QuickHelpCategory.CAREER_GUIDANCE]: 'secondary-100 text-secondary',
      [QuickHelpCategory.FRIENDSHIP_SOCIAL]: 'accent-100 text-accent',
      [QuickHelpCategory.SLEEP_WELLBEING]: 'primary-100 text-primary',
      [QuickHelpCategory.GENERAL_SUPPORT]: 'secondary-100 text-secondary',
      [QuickHelpCategory.NOT_SURE]: 'gray-100 text-gray',
      [QuickHelpCategory.URGENT_HELP]: 'error-light text-error'
    };
    return colors[category] || 'primary-100 text-primary';
  }

  getPathwayLabel(pathway: SupportPathway): string {
    return SUPPORT_PATHWAYS[pathway].title;
  }

  selectOption(option: any): void {
    const pathway = SUPPORT_PATHWAYS[option.recommendedPathway];
    if (pathway) {
      window.location.href = pathway.actionRoute;
    }
  }
}