export class WellnessResourcesComponent implements OnInit {
  user = { firstName: 'John' };

  resources: WellnessResource[] = [];
  filteredResources: WellnessResource[] = [];
  academyCourses: WellnessAcademyCourse[] = [];

  searchQuery = '';
  selectedCategory = '';
  selectedFormat = '';
  activeResourceTab = 'library';

  categories = [
    { value: ResourceCategory.MENTAL_HEALTH, label: 'Mental Health' },
    { value: ResourceCategory.STRESS_MANAGEMENT, label: 'Stress Management' },
    { value: ResourceCategory.ACADEMIC_SUCCESS, label: 'Academic Success' },
    { value: ResourceCategory.RELATIONSHIPS, label: 'Relationships' },
    { value: ResourceCategory.SLEEP_WELLNESS, label: 'Sleep Wellness' },
    { value: ResourceCategory.MINDFULNESS, label: 'Mindfulness' },
    { value: ResourceCategory.CRISIS_SUPPORT, label: 'Crisis Support' },
    { value: ResourceCategory.CAREER_GUIDANCE, label: 'Career Guidance' }
  ];

  formats = [
    { value: 'article', label: 'Article' },
    { value: 'video', label: 'Video' },
    { value: 'podcast', label: 'Podcast' },
    { value: 'tool', label: 'Tool' },
    { value: 'worksheet', label: 'Worksheet' }
  ];

  resourceTabs = [
    { id: 'library', label: 'Resource Library' },
    { id: 'academy', label: 'Wellness Academy' },
    { id: 'tools', label: 'Self-Help Tools' }
  ];

  navItems: NavItem[] = [
    { label: 'Dashboard', route: '/student/dashboard', icon: 'dashboard' },
    { label: 'Quick Help', route: '/student/quick-help', icon: 'help' },
    { label: 'Mood Check-in', route: '/student/mood-checkin', icon: 'activity' },
    { label: 'Quiet Space', route: '/student/quiet-space', icon: 'moon' },
    { label: 'Resources', route: '/student/wellness-resources', icon: 'book', active: true }
  ];

  bottomNavItems = [
    { label: 'Home', route: '/student/dashboard', icon: 'home' },
    { label: 'Help', route: '/student/quick-help', icon: 'help' },
    { label: 'Mood', route: '/student/mood-checkin', icon: 'activity' },
    { label: 'Quiet', route: '/student/quiet-space', icon: 'moon' },
    { label: 'Profile', route: '/student/profile', icon: 'user' }
  ];

  constructor(private resourceService: WellnessResourceService) {}

  ngOnInit(): void {
    this.resources = this.resourceService.getResources();
    this.academyCourses = this.resourceService.getAcademyCourses();
    this.filteredResources = [...this.resources];
  }

  setActiveResourceTab(tabId: string): void {
    this.activeResourceTab = tabId;
  }

  filterResources(): void {
    this.filteredResources = this.resources.filter(r => {
      const matchesSearch = !this.searchQuery || 
        r.title.toLowerCase().includes(this.searchQuery.toLowerCase()) ||
        r.description.toLowerCase().includes(this.searchQuery.toLowerCase()) ||
        r.tags.some(t => t.toLowerCase().includes(this.searchQuery.toLowerCase()));
      const matchesCategory = !this.selectedCategory || r.category === this.selectedCategory;
      const matchesFormat = !this.selectedFormat || r.format === this.selectedFormat;
      return matchesSearch && matchesCategory && matchesFormat;
    });
  }

  getCategoryIcon(category: ResourceCategory): string {
    const icons: Record<ResourceCategory, string> = {
      [ResourceCategory.MENTAL_HEALTH]: '<path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="M12 6v6l4 2"></path>',
      [ResourceCategory.STRESS_MANAGEMENT]: '<path d="M17 21v-2a4 4 0 0 0-4-4H5a4 4 0 0 0-4 4v2"></path><circle cx="9" cy="7" r="4"></circle>',
      [ResourceCategory.ACADEMIC_SUCCESS]: '<path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20"></path><path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z"></path>',
      [ResourceCategory.RELATIONSHIPS]: '<path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path>',
      [ResourceCategory.SLEEP_WELLNESS]: '<path d="M12 22c5.523 0 10-4.477 10-10S17.523 2 12 2 2 6.477 2 12s4.477 10 10 10z"></path><path d="M12 6v6l4 2"></path>',
      [ResourceCategory.MINDFULNESS]: '<circle cx="12" cy="12" r="3"></circle><path d="M12 2v2"></path><path d="M12 20v2"></path><path d="M2 12h2"></path><path d="M20 12h2"></path>',
      [ResourceCategory.CRISIS_SUPPORT]: '<path d="M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z"></path><line x1="12" y1="9" x2="12" y2="13"></line><line x1="12" y1="17" x2="12.01" y2="17"></line>',
      [ResourceCategory.CAREER_GUIDANCE]: '<path d="M22 12h-4l-3 9L9 3l-3 9H2"></path>'
    };
    return icons[category] || icons[ResourceCategory.MENTAL_HEALTH];
  }

  getCategoryColor(category: ResourceCategory): string {
    const colors: Record<ResourceCategory, string> = {
      [ResourceCategory.MENTAL_HEALTH]: 'primary-100',
      [ResourceCategory.STRESS_MANAGEMENT]: 'warning-light',
      [ResourceCategory.ACADEMIC_SUCCESS]: 'secondary-100',
      [ResourceCategory.RELATIONSHIPS]: 'accent-100',
      [ResourceCategory.SLEEP_WELLNESS]: 'primary-100',
      [ResourceCategory.MINDFULNESS]: 'accent-100',
      [ResourceCategory.CRISIS_SUPPORT]: 'error-light',
      [ResourceCategory.CAREER_GUIDANCE]: 'secondary-100'
    };
    return colors[category] || 'primary-100';
  }

  getFormatVariant(format: string): string {
    const variants: Record<string, string> = {
      'article': 'secondary',
      'video': 'primary',
      'podcast': 'accent',
      'tool': 'warning',
      'worksheet': 'success'
    };
    return variants[format] || 'secondary';
  }

  openResource(resource: WellnessResource): void {
    console.log('Open resource:', resource.id);
  }

  openCourse(course: WellnessAcademyCourse): void {
    console.log('Open course:', course.id);
  }

  openTool(toolId: string): void {
    console.log('Open tool:', toolId);
  }
}