  constructor() {}

  getResources(): WellnessResource[] {
    return [...this.resources].sort((a, b) => {
      if (a.isFeatured && !b.isFeatured) return -1;
      if (!a.isFeatured && b.isFeatured) return 1;
      return b.views - a.views;
    });
  }

  getAcademyCourses(): WellnessAcademyCourse[] {
    return [...this.academyCourses].sort((a, b) => b.enrolled - a.enrolled);
  }

  getResourceById(id: string): WellnessResource | undefined {
    return this.resources.find(r => r.id === id);
  }

  getCourseById(id: string): WellnessAcademyCourse | undefined {
    return this.academyCourses.find(c => c.id === id);
  }

  getResourcesByCategory(category: ResourceCategory): WellnessResource[] {
    return this.resources.filter(r => r.category === category);
  }

  getResourcesByFormat(format: WellnessResource['format']): WellnessResource[] {
    return this.resources.filter(r => r.format === format);
  }

  searchResources(query: string): WellnessResource[] {
    const lowerQuery = query.toLowerCase();
    return this.resources.filter(r =>
      r.title.toLowerCase().includes(lowerQuery) ||
      r.description.toLowerCase().includes(lowerQuery) ||
      r.tags.some(t => t.toLowerCase().includes(lowerQuery))
    );
  }

  getFeaturedResources(limit: number = 3): WellnessResource[] {
    return this.resources
      .filter(r => r.isFeatured)
      .sort((a, b) => b.views - a.views)
      .slice(0, limit);
  }

  getPopularResources(limit: number = 5): WellnessResource[] {
    return [...this.resources]
      .sort((a, b) => b.views - a.views)
      .slice(0, limit);
  }

  getRecentResources(limit: number = 5): WellnessResource[] {
    return [...this.resources]
      .sort((a, b) => new Date(b.publishDate || 0).getTime() - new Date(a.publishDate || 0).getTime())
      .slice(0, limit);
  }
